// No cache. One request reads the folder once.
public function listFiles(): array
{
    $files = [];
    foreach (scandir($this->storagePath) as $name) {
        $path = $this->storagePath . '/' . $name;
        if (is_file($path) && $this->isSupported($name)) {
            $files[] = $name;
        }
    }
    return $files;
}

